window.docContents[249].resolve({"/Decidability___-Finiteness-and-Degrees/#section-finite-types":{"contents":"The main constructive way of expressing that a type is finite in Mathlib is via the\nFintype class. Before we discuss Fintype we introduce the three closely\nrelated data structures that underlie almost all finite reasoning in Mathlib:\nList, Multiset and Finset.\n\n\n\n\n\n\n\n\n\n","context":"Graph Theory in Lean\u0009Decidability, Finiteness and Degrees","header":"4.2. Finite Types","id":"/Decidability___-Finiteness-and-Degrees/#section-finite-types"}});